mapper.select:
SELECT r.REPORT_ID, r.REPORT_CODE, r.REPORT_NAME, r.REPORT_TYPE, r.MODEL_ID, r.QUERY_CONDITION, r.DISPLAY_COLUMNS, r.SORT_CONFIG, r.FILTER_CONFIG, r.IS_TEMPLATE, r.IS_PUBLIC, r.DESCRIPTION, r.ORG_ID, r.CREATE_USER, r.CREATE_TIME, r.UPDATE_USER, r.UPDATE_TIME, m.MODEL_NAME FROM TBL_BUDGET_REPORT r LEFT JOIN TBL_BUDGET_MODEL m ON r.MODEL_ID = m.MODEL_ID
AND r.ORG_ID = #{param.orgId}
AND r.REPORT_TYPE = #{param.reportType}
AND r.MODEL_ID = #{param.modelId}
ORDER BY r.CREATE_TIME DESC

SELECT be.EXECUTION_ID AS "executionId", be.MODEL_ID AS "modelId", COALESCE(m.MODEL_NAME, be.MODEL_ID) AS "modelName", be.ORG_ID AS "orgId", be.BIZ_ORG_ID AS "bizOrgId", be.ORG_CODE AS "orgCode", COALESCE(be.ORG_NAME, be.ORG_CODE, be.BIZ_ORG_ID, '-') AS "orgName", be.SUBJECT_CODE AS "subjectCode", COALESCE(be.SUBJECT_NAME, be.SUBJECT_CODE, '-') AS "subjectName", be.PERIOD AS "period", be.BUDGET_YEAR AS "budgetYear", be.VERSION_NO AS "versionNo", be.DIMENSION1_CODE AS "dimension1Code", COALESCE(be.DIMENSION1_NAME, be.DIMENSION1_CODE) AS "dimension1Name", be.DIMENSION2_CODE AS "dimension2Code", COALESCE(be.DIMENSION2_NAME, be.DIMENSION2_CODE) AS "dimension2Name", NVL(be.BUDGET_AMOUNT, 0) AS "budgetAmount", NVL(be.ADJUSTED_AMOUNT, 0) AS "adjustedAmount", NVL(be.ACTUAL_AMOUNT, 0) AS "actualAmount", NVL(be.COMMITTED_AMOUNT, 0) AS "committedAmount", NVL(be.OCCUPIED_AMOUNT, 0) AS "occupiedAmount", NVL(be.AVAILABLE_AMOUNT, 0) AS "availableAmount", NVL(be.VARIANCE_AMOUNT, 0) AS "varianceAmount", NVL(be.VARIANCE_RATE, 0) AS "varianceRate", NVL(be.EXECUTION_RATE, 0) AS "executionRate", be.STATUS AS "status", be.WARNING_LEVEL AS "warningLevel", 'EXECUTION' AS "dataSource" FROM TBL_BUDGET_EXECUTION be LEFT JOIN TBL_BUDGET_MODEL m ON be.MODEL_ID = m.MODEL_ID
AND be.ORG_ID = #{param.orgId}
AND be.MODEL_ID = #{param.modelId}
AND be.BIZ_ORG_ID IN
#{oid}
AND be.SUBJECT_CODE IN
#{code}
AND be.PERIOD IN
#{period}
AND be.PERIOD >= #{param.startPeriod}
AND be.PERIOD <= #{param.endPeriod}
AND be.BUDGET_YEAR = #{param.budgetYear}
AND be.VERSION_NO = #{param.versionNo}
ORDER BY be.PERIOD, be.SUBJECT_CODE

SELECT
be.BIZ_ORG_ID AS "dimensionValue", MAX(be.ORG_NAME) AS "dimensionName",
be.SUBJECT_CODE AS "dimensionValue", MAX(be.SUBJECT_NAME) AS "dimensionName",
be.PERIOD AS "dimensionValue", MAX(be.PERIOD) AS "dimensionName",
be.BIZ_ORG_ID AS "dimensionValue", MAX(be.ORG_NAME) AS "dimensionName",
SUM(NVL(be.BUDGET_AMOUNT, 0)) AS "totalBudgetAmount", SUM(NVL(be.ADJUSTED_AMOUNT, 0)) AS "totalAdjustedAmount", SUM(NVL(be.ACTUAL_AMOUNT, 0)) AS "totalActualAmount", SUM(NVL(be.VARIANCE_AMOUNT, 0)) AS "totalVarianceAmount", CASE WHEN SUM(NVL(be.ADJUSTED_AMOUNT, 0)) = 0 THEN 0 ELSE ROUND(SUM(NVL(be.ACTUAL_AMOUNT, 0)) / SUM(be.ADJUSTED_AMOUNT) * 100, 2) END AS "executionRate" FROM TBL_BUDGET_EXECUTION be
AND be.ORG_ID = #{param.orgId}
AND be.MODEL_ID = #{param.modelId}
AND be.BIZ_ORG_ID IN
#{oid}
AND be.SUBJECT_CODE IN
#{code}
AND be.PERIOD >= #{param.startPeriod}
AND be.PERIOD <= #{param.endPeriod}
AND be.BUDGET_YEAR = #{param.budgetYear}
GROUP BY
be.BIZ_ORG_ID
be.SUBJECT_CODE
be.PERIOD
be.BIZ_ORG_ID
ORDER BY "dimensionValue"

choose.when:
SELECT be.SUBJECT_CODE AS "subjectCode", MAX(be.SUBJECT_NAME) AS "subjectName", be.PERIOD AS "period", SUM(NVL(be.BUDGET_AMOUNT, 0)) AS "budgetAmount", SUM(NVL(be.ADJUSTED_AMOUNT, 0)) AS "adjustedAmount", SUM(NVL(be.ACTUAL_AMOUNT, 0)) AS "actualAmount", SUM(NVL(be.VARIANCE_AMOUNT, 0)) AS "varianceAmount", CASE WHEN SUM(NVL(be.ADJUSTED_AMOUNT, 0)) = 0 THEN 0 ELSE ROUND(SUM(NVL(be.ACTUAL_AMOUNT, 0)) / SUM(be.ADJUSTED_AMOUNT) * 100, 2) END AS "executionRate" FROM TBL_BUDGET_EXECUTION be
AND be.ORG_ID = #{param.orgId}
AND be.MODEL_ID = #{param.modelId}
AND be.BIZ_ORG_ID IN
#{oid}
AND be.SUBJECT_CODE IN
#{code}
AND be.PERIOD >= #{param.startPeriod}
AND be.PERIOD <= #{param.endPeriod}
AND be.BUDGET_YEAR = #{param.budgetYear}
GROUP BY be.SUBJECT_CODE, be.PERIOD ORDER BY be.PERIOD, be.SUBJECT_CODE

choose.otherwise:
SELECT be.SUBJECT_CODE AS "subjectCode", MAX(be.SUBJECT_NAME) AS "subjectName", be.PERIOD AS "period", SUM(NVL(be.BUDGET_AMOUNT, 0)) AS "budgetAmount", SUM(NVL(be.ACTUAL_AMOUNT, 0)) AS "actualAmount" FROM TBL_BUDGET_EXECUTION be
AND be.ORG_ID = #{param.orgId}
AND be.MODEL_ID = #{param.modelId}
AND be.BIZ_ORG_ID IN
#{oid}
AND be.BUDGET_YEAR = #{param.budgetYear}
GROUP BY be.SUBJECT_CODE, be.PERIOD ORDER BY be.PERIOD, be.SUBJECT_CODE

mapper.select:
SELECT
    be.PERIOD                        AS "period",
    SUM(NVL(be.BUDGET_AMOUNT,   0))  AS "budgetAmount",
    SUM(NVL(be.ADJUSTED_AMOUNT, 0))  AS "adjustedAmount",
    SUM(NVL(be.ACTUAL_AMOUNT,   0))  AS "actualAmount",
    SUM(NVL(be.VARIANCE_AMOUNT, 0))  AS "varianceAmount",
    CASE
        WHEN SUM(NVL(be.ADJUSTED_AMOUNT, 0)) = 0 THEN 0
        ELSE ROUND(SUM(NVL(be.ACTUAL_AMOUNT, 0)) / SUM(be.ADJUSTED_AMOUNT) * 100, 2)
    END                              AS "executionRate"
FROM TBL_BUDGET_EXECUTION be


        AND be.ORG_ID = #{param.orgId}


        AND be.MODEL_ID = #{param.modelId}


        AND be.BIZ_ORG_ID IN

            #{oid}



        AND be.SUBJECT_CODE IN

            #{code}



        AND be.PERIOD >= #{param.startPeriod}


        AND be.PERIOD <= #{param.endPeriod}


        AND be.BUDGET_YEAR = #{param.budgetYear}


GROUP BY be.PERIOD
ORDER BY be.PERIOD
